/// <summary>
/// One batch task of HSMobileOpsTestDataGenerator: creates one purchase order (PO), transfer
/// order (TO) or counting journal (COUNT) in BSP over the HSV test variants. Each document is
/// one transaction, so a failure leaves nothing half made. Tasks of one job run in parallel.
/// </summary>
class HSMobileOpsTestDataTask extends RunBaseBatch
{
    str kind;
    int docNumber;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        kind,
        docNumber
    #endmacro
}

Method.Source:
/// <summary>
/// Runs in the foreground (&amp;cls=HSMobileOpsTestDataTask): the mixed purchase order and
/// transfer order - one line per kind of item, with and without variants and tracking.
/// </summary>
public static void main(Args _args)
{
    changecompany ('BSP')
    {
        HSMobileOpsTestDataGenerator::ensureMixItems();
    }
    // Earlier runs made the mixed PO and TOs; this run makes a counting journal from AAC's
    // on-hand of items no other open counting journal has (plain, batch and serial).
    HSMobileOpsTestDataTask::newTask('COUNTMIX', 1).run();
}

public static HSMobileOpsTestDataTask newTask(str _kind, int _index)
{
    HSMobileOpsTestDataTask task = new HSMobileOpsTestDataTask();

    task.parmKind(_kind);
    task.parmDocNumber(_index);
    task.batchInfo().parmCaption(strFmt('HS test data %1 %2', _kind, _index));
    return task;
}

public str parmKind(str _value = kind)
{
    kind = _value;
    return kind;
}

public int parmDocNumber(int _value = docNumber)
{
    docNumber = _value;
    return docNumber;
}

public boolean unpack(container _packedClass)
{
    int version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            return true;
        default:
            return false;
    }
}

public static ClassDescription description()
{
    return 'HS mobile ops test data task';
}

public void run()
{
    changecompany ('BSP')
    {
        switch (kind)
        {
            case 'PO':
                this.createPurchaseOrder(110);
                break;
            case 'TO':
                this.createTransferOrder(520);
                break;
            case 'COUNT':
                this.createCountingJournal(2040);
                break;
            case 'POT':
                this.createPurchaseOrder(108, true);
                break;
            case 'TOT':
                this.createTransferOrder(108, true);
                break;
            case 'MIXPO':
                this.createMixedPurchaseOrder();
                break;
            case 'MIXTO':
                this.createMixedTransferOrder(HSMobileOpsTestDataGenerator::mixLines());
                break;
            case 'COUNTMIX':
                this.createCountingFromOnHand(['HSN001', 'HSN002', 'HST001', 'HST002', 'HST003']);
                break;
            case 'MIXTO2':
                this.createMixedTransferOrder([
                    ['HSN001', '', '', '', '', 0, 1],
                    ['HST002', 'C1', 'M', 'Blue', 'Regular', 0, 1]]);
                break;
        }
    }
}

/// <summary>Line _j's variant, offset per document so documents differ.</summary>
private container variant(int _j, boolean _tracked = false)
{
    return HSMobileOpsTestDataGenerator::variantAt(_j + (docNumber - 1) * 37, _tracked);
}

private void createPurchaseOrder(int _lines, boolean _tracked = false)
{
    PurchTable purchTable;
    PurchLine  purchLine;
    container  v;
    ItemId     itemId;
    str        config, size, color, style;
    int        j;

    ttsbegin;
    purchTable.clear();
    purchTable.initValue();
    purchTable.PurchId      = NumberSeq::newGetNum(PurchParameters::numRefPurchId()).num();
    purchTable.OrderAccount = '19721';
    purchTable.initFromVendTable(VendTable::find(purchTable.OrderAccount));
    purchTable.InventSiteId     = 'AAC';
    purchTable.InventLocationId = 'AAC';
    purchTable.DeliveryDate     = today();
    purchTable.insert();

    for (j = 0; j < _lines; j++)
    {
        v = this.variant(j, _tracked);
        [itemId, config, size, color, style] = v;
        purchLine.clear();
        purchLine.initFromPurchTable(purchTable);
        purchLine.ItemId      = itemId;
        purchLine.InventDimId = HSMobileOpsTestDataGenerator::variantDimId(itemId, config, size, color, style, true, 'AAC', 'AAC');
        purchLine.PurchQty    = 1 + (j mod 10);
        purchLine.createLine(true, false, true, true, true, true);
    }
    ttscommit;

    HSMobileOpsCreateVariantTestPO::confirm(purchTable);
    info(strFmt('PO %1: %2 lines', purchTable.PurchId, _lines));
}

private void createTransferOrder(int _lines, boolean _tracked = false)
{
    InventTransferTable transferTable;
    InventTransferLine  transferLine;
    container           v;
    ItemId              itemId;
    str                 config, size, color, style;
    int                 j;
    real                qty;

    ttsbegin;
    transferTable.clear();
    transferTable.initValue();
    transferTable.TransferId           = NumberSeq::newGetNum(InventParameters::numRefTransferId()).num();
    transferTable.InventLocationIdFrom = 'AAC';
    transferTable.modifiedField(fieldNum(InventTransferTable, InventLocationIdFrom));
    transferTable.InventLocationIdTo   = 'ABB';
    transferTable.modifiedField(fieldNum(InventTransferTable, InventLocationIdTo));
    transferTable.ShipDate             = today();
    transferTable.ReceiveDate          = today();
    transferTable.insert();

    for (j = 0; j < _lines; j++)
    {
        v = this.variant(j, _tracked);
        [itemId, config, size, color, style] = v;
        qty = 1 + (j mod 5);
        transferLine.clear();
        transferLine.initValue();
        transferLine.initFromInventTransferTable(transferTable, NoYes::Yes);
        transferLine.ItemId = itemId;
        transferLine.initFromInventTable(InventTable::find(itemId));
        // Warehouse-management warehouse: a transfer line needs an inventory status.
        transferLine.InventDimId      = HSMobileOpsTestDataGenerator::variantDimId(itemId, config, size, color, style, true, 'AAC', 'AAC', '', 'Available');
        transferLine.QtyTransfer      = qty;
        transferLine.QtyRemainShip    = qty;
        transferLine.QtyRemainReceive = qty;
        transferLine.LineNum          = j + 1;
        transferLine.insert();
    }
    ttscommit;
    info(strFmt('TO %1: %2 lines', transferTable.TransferId, _lines));
}

/// <summary>A confirmed PO to AAC with one line per kind of item (HSMobileOpsTestDataGenerator::mixLines).</summary>
private void createMixedPurchaseOrder()
{
    PurchTable purchTable;
    PurchLine  purchLine;
    container  lines = HSMobileOpsTestDataGenerator::mixLines(), v;
    ItemId     itemId;
    str        config, size, color, style;
    real       poQty, toQty;
    int        j;

    ttsbegin;
    purchTable.clear();
    purchTable.initValue();
    purchTable.PurchId      = NumberSeq::newGetNum(PurchParameters::numRefPurchId()).num();
    purchTable.OrderAccount = '19721';
    purchTable.initFromVendTable(VendTable::find(purchTable.OrderAccount));
    purchTable.InventSiteId     = 'AAC';
    purchTable.InventLocationId = 'AAC';
    purchTable.DeliveryDate     = today();
    purchTable.insert();

    for (j = 1; j <= conLen(lines); j++)
    {
        v = conPeek(lines, j);
        [itemId, config, size, color, style, poQty, toQty] = v;
        purchLine.clear();
        purchLine.initFromPurchTable(purchTable);
        purchLine.ItemId      = itemId;
        purchLine.InventDimId = HSMobileOpsTestDataGenerator::variantDimId(itemId, config, size, color, style, true, 'AAC', 'AAC');
        purchLine.PurchQty    = poQty;
        purchLine.createLine(true, false, true, true, true, true);
    }
    ttscommit;

    HSMobileOpsCreateVariantTestPO::confirm(purchTable);
    info(strFmt('Mixed PO %1: %2 lines', purchTable.PurchId, conLen(lines)));
}

/// <summary>
/// A TO AAC to ABB with one line per kind of item. Batch and serial are left open on the
/// lines: they are chosen when shipping, from what the mixed PO's receipt put in stock.
/// </summary>
private void createMixedTransferOrder(container _lines)
{
    InventTransferTable transferTable;
    InventTransferLine  transferLine;
    container           lines = _lines, v;
    ItemId              itemId;
    str                 config, size, color, style;
    real                poQty, toQty;
    int                 j;

    ttsbegin;
    transferTable.clear();
    transferTable.initValue();
    transferTable.TransferId           = NumberSeq::newGetNum(InventParameters::numRefTransferId()).num();
    transferTable.InventLocationIdFrom = 'AAC';
    transferTable.modifiedField(fieldNum(InventTransferTable, InventLocationIdFrom));
    transferTable.InventLocationIdTo   = 'ABB';
    transferTable.modifiedField(fieldNum(InventTransferTable, InventLocationIdTo));
    transferTable.ShipDate             = today();
    transferTable.ReceiveDate          = today();
    transferTable.insert();

    for (j = 1; j <= conLen(lines); j++)
    {
        v = conPeek(lines, j);
        [itemId, config, size, color, style, poQty, toQty] = v;
        transferLine.clear();
        transferLine.initValue();
        transferLine.initFromInventTransferTable(transferTable, NoYes::Yes);
        transferLine.ItemId = itemId;
        transferLine.initFromInventTable(InventTable::find(itemId));
        // Warehouse-management warehouse: a transfer line needs an inventory status.
        transferLine.InventDimId      = HSMobileOpsTestDataGenerator::variantDimId(itemId, config, size, color, style, true, 'AAC', 'AAC', '', 'Available');
        transferLine.QtyTransfer      = toQty;
        transferLine.QtyRemainShip    = toQty;
        transferLine.QtyRemainReceive = toQty;
        transferLine.LineNum          = j;
        transferLine.insert();
    }
    ttscommit;
    info(strFmt('Mixed TO %1: %2 lines', transferTable.TransferId, conLen(lines)));
}

/// <summary>
/// A counting journal at AAC with one line per on-hand dimension (variant, location, batch,
/// serial, status) of the given items - so each line is what is physically there.
/// </summary>
private void createCountingFromOnHand(container _items)
{
    InventJournalTable journalTable;
    InventJournalTrans journalTrans;
    InventJournalName  journalName = InventJournalName::find(InventJournalTable::find('BSP-JN-000552000').JournalNameId);
    InventSum          inventSum;
    InventDim          inventDim;
    int                i, lineNum;

    ttsbegin;
    journalTable.clear();
    journalTable.initValue();
    journalTable.JournalNameId = journalName.JournalNameId;
    journalTable.initFromInventJournalName(journalName);
    journalTable.JournalId   = NumberSeq::newGetNum(InventParameters::numRefInventJournalId()).num();
    journalTable.Description = 'HS test counting - tracked and plain items';
    journalTable.insert();

    for (i = 1; i <= conLen(_items); i++)
    {
        while select inventSum
            where inventSum.ItemId         == conPeek(_items, i)
               && inventSum.Closed         == NoYes::No
               && inventSum.PhysicalInvent >  0
            join inventDim
                where inventDim.inventDimId      == inventSum.InventDimId
                   && inventDim.InventLocationId == 'AAC'
        {
            lineNum++;
            journalTrans.clear();
            journalTrans.initValue();
            journalTrans.initFromInventJournalTable(journalTable);
            journalTrans.TransDate   = today();
            journalTrans.ItemId      = inventSum.ItemId;
            journalTrans.initFromInventTable(InventTable::find(inventSum.ItemId));
            journalTrans.InventDimId = inventDim.inventDimId;
            journalTrans.InventOnHand = inventSum.PhysicalInvent;
            journalTrans.LineNum     = lineNum;
            journalTrans.insert();
        }
    }
    journalTable.selectForUpdate(true);
    journalTable.NumOfLines = lineNum;
    journalTable.update();
    ttscommit;
    info(strFmt('Counting journal %1: %2 lines from on-hand', journalTable.JournalId, lineNum));
}

/// <summary>
/// A counting journal at AAC: each line one variant at one location (locations whose
/// profile is not license-plate controlled, so a line needs no license plate).
/// </summary>
private void createCountingJournal(int _lines)
{
    InventJournalTable  journalTable;
    InventJournalTrans  journalTrans;
    InventJournalName   journalName = InventJournalName::find(InventJournalTable::find('BSP-JN-000552000').JournalNameId);
    WMSLocation         wmsLocation;
    WHSLocationProfile  profile;
    container           v, locs;
    ItemId              itemId;
    str                 config, size, color, style;
    int                 j, nVariants = HSMobileOpsTestDataGenerator::variantCount();

    while select wMSLocationId from wmsLocation
        order by wMSLocationId
        where wmsLocation.inventLocationId == 'AAC'
        notexists join profile
            where profile.LocProfileId == wmsLocation.LocProfileId
               && profile.LPControlled == NoYes::Yes
    {
        locs += wmsLocation.wMSLocationId;
    }
    if (!conLen(locs))
    {
        locs = [''];
    }

    ttsbegin;
    journalTable.clear();
    journalTable.initValue();
    journalTable.JournalNameId = journalName.JournalNameId;
    journalTable.initFromInventJournalName(journalName);
    journalTable.JournalId   = NumberSeq::newGetNum(InventParameters::numRefInventJournalId()).num();
    journalTable.Description = strFmt('HS test counting %1', docNumber);
    journalTable.insert();

    for (j = 0; j < _lines; j++)
    {
        v = this.variant(j mod nVariants);
        [itemId, config, size, color, style] = v;
        journalTrans.clear();
        journalTrans.initValue();
        journalTrans.initFromInventJournalTable(journalTable);
        journalTrans.TransDate = today();
        journalTrans.ItemId    = itemId;
        journalTrans.initFromInventTable(InventTable::find(itemId));
        journalTrans.InventDimId = HSMobileOpsTestDataGenerator::variantDimId(itemId, config, size, color, style, true,
            'AAC', 'AAC', conPeek(locs, 1 + ((j div nVariants) mod conLen(locs))));
        journalTrans.LineNum = j + 1;
        journalTrans.insert();
    }
    journalTable.selectForUpdate(true);
    journalTable.NumOfLines = _lines;
    journalTable.update();
    ttscommit;
    info(strFmt('Counting journal %1: %2 lines over %3 locations', journalTable.JournalId, _lines, conLen(locs)));
}
